# SARIMA grid on log y no exog, pick AIC
best=[]
ly=np.log(y)
for order in [(p,d,q) for p in range(3) for d in [0,1] for q in range(3)]:
    for seas in [(P,D,Q,12) for P in range(2) for D in [0,1] for Q in range(2)]:
        try:
            fit=SARIMAX(ly, order=order, seasonal_order=seas, enforce_stationarity=False, enforce_invertibility=False).fit(disp=False, maxiter=200)
            best.append((fit.aic, order, seas, fit))
        except Exception as e:
            pass
best_sorted=sorted(best, key=lambda x: x[0])
[(a,o,s) for a,o,s,f in best_sorted[:10]]

